// Shape the canonical JSON for your ledger / ERP node
const inv = $input.first().json.invoice;
return [{ json: {
  number: inv.document.id,
  date: inv.document.issue_date,
  due: inv.document.due_date,
  currency: inv.document.currency,
  supplier: inv.seller?.name,
  supplier_vat: inv.seller?.vat_id,
  net: inv.totals.net,
  vat: inv.totals.tax,
  gross: inv.totals.gross,
  iban: inv.payment?.credit_transfers?.[0]?.iban,
  lines: (inv.lines || []).map(l => ({ name: l.item?.name, qty: l.quantity, net: l.net_amount, vat_rate: l.tax?.rate })),
} }];

// Forward the fix hints to whoever talks to the supplier
const v = $input.first().json.validation;
const text = v.issues.map(i => `• ${i.id} (${i.severity}): ${i.hint || i.message}`).join('\n');
return [{ json: { subject: `Invoice rejected: ${v.errors} error(s)`, text } }];
